mapper.select:
with tr as ( select t.booking_number, t.flight_id, t.name, t.date, t.`from`, t.`to`, t.booking_status, t.booking_class from tb_record as t where t.passenger_id in
#{id}
and t.is_deleted = 0 ) select tr.*,fp.price from tr left join tb_flight_price fp on tr.flight_id = fp.flight_id and fp.seat_type = tr.booking_class and fp.status = 1 and fp.is_deleted = 0 ;
